SELECT row_id, action, status, stage, sent, total, wait, attempts, error_kind, error_message, size, sync_upload.transfer_id, batch, round_error, progress, source, CASE WHEN batch IS NULL THEN NULL ELSE batch_progress END, outcome.kind, outcome.value FROM sync_upload LEFT JOIN transfer_outcome AS outcome ON outcome.transfer_id = sync_upload.transfer_id AND outcome.cycle_id = sync_upload.cycle_id WHERE model = ? AND row_id IN ({marks})
